
"use client"
import React, { useEffect } from "react"
import axios from "axios"
import Link from "next/link"
import { toast } from 'react-hot-toast';
import { useRouter } from 'next/navigation';
import AddTodoForm from "./addtodoform";

export default function Dashboard(){
    const router = useRouter()

    const [user,setUser]:any = React.useState("")



  

    const getCurrentUser = async () => {
        try {
            const response = await axios.get("/api/auth/me");
            setUser(response.data.user);
        } catch (error) {
            console.log("User not logged in");
            router.push("/login");  // if user is not logged in 
        }
    }

    useEffect(()=>{
        getCurrentUser()
    },[])


    return (
        <div className="min-h-screen bg-gray-950 text-white flex flex-col md:flex-row">
            <aside className="w-full md:w-64 bg-gray-900 p-6 border-r border-gray-800 flex flex-col justify-between">
                <div>
                <h2 className="text-2xl font-bold mb-6">TaskForge</h2>
                <nav className="space-y-4">
                    <Link href="#" className="block text-gray-300 hover:text-white">Dashboard</Link>
                    <Link href="#" className="block text-gray-300 hover:text-white">Completed</Link>
                    <Link href="#" className="block text-gray-300 hover:text-white">Settings</Link>
                </nav>
                </div>
                <div className="mt-6 border-t border-gray-700 pt-4">
                <p className="text-sm text-gray-400">Logged in as</p>
                <p className="font-semibold">
                    {user.email ? user.email : "Guest"}
                </p>
                </div>
            </aside>

            <main className="flex-1 p-6">
                <header className="flex items-center justify-between mb-6">
                <h1 className="text-3xl font-semibold">Dashboard</h1>
                <button className="bg-blue-600 px-4 py-2 rounded-lg hover:bg-blue-700 transition">Add Task</button>
                </header>

                {user._id && <AddTodoForm userId={user._id} />}


                <section className="grid gap-4 grid-cols-1 sm:grid-cols-2 lg:grid-cols-3">
                <div className="bg-gray-800 p-4 rounded-lg shadow hover:shadow-lg transition">
                    <h2 className="text-xl font-bold mb-2">Finish Portfolio</h2>
                    <p className="text-sm text-gray-400 mb-2">Due: 2025-05-10</p>
                    <p className="text-sm text-gray-300 mb-4">Update layout and deploy to GitHub Pages.</p>
                    <span className="text-xs px-2 py-1 bg-yellow-500 text-black rounded-full">Pending</span>
                </div>
                </section>
            </main>
        </div>

    )
}